<template><div class="page-card payment-page" v-loading="loading"><div class="page-lead"><div><h2>收款登记</h2><p>登记实际到账金额并分配到一笔应收账单；保存后同步核销应收并生成实收流水。</p></div><div class="page-lead-actions"><el-button @click="router.push('/transactions')">未明确合同，先登记挂账</el-button></div></div><div class="payment-layout"><section class="bill-picker"><h3>选择待收账单</h3><el-input v-model="keyword" clearable placeholder="搜索客户、合同或广告牌" class="bill-search"/><div class="bill-list"><button v-for="item in filtered" :key="item.id" type="button" :class="{active:selected?.id===item.id}" @click="select(item)"><span><b>{{item.merchantName}}</b><small>{{item.contractCode}} · {{item.billboardCode}} · {{item.year}}年</small></span><strong>欠 ¥ {{fmtMoney(item.amount-item.received)}}</strong></button><el-empty v-if="!filtered.length" :image-size="60" description="没有待收账单"/></div></section><section class="payment-form"><template v-if="selected"><header><span>本次核销账单</span><h3>{{selected.contractCode}} / {{selected.year}} 年</h3></header><el-descriptions :column="1" border><el-descriptions-item label="客户">{{selected.merchantName}}</el-descriptions-item><el-descriptions-item label="广告牌">{{selected.billboardCode}}</el-descriptions-item><el-descriptions-item label="应收金额">¥ {{fmtMoney(selected.amount)}}</el-descriptions-item><el-descriptions-item label="已收金额">¥ {{fmtMoney(selected.received)}}</el-descriptions-item><el-descriptions-item label="剩余欠款"><span class="red">¥ {{fmtMoney(remain)}}</span></el-descriptions-item></el-descriptions><el-form label-width="90px" class="amount-form"><el-form-item label="本次收款" required><el-input-number v-model="amount" :min="0.01" :max="remain" :precision="2" :controls="false" style="width:100%"/></el-form-item><el-form-item><el-checkbox @change="(v:boolean)=>v&&(amount=remain)">本次全额收款</el-checkbox></el-form-item></el-form><el-alert type="info" :closable="false" show-icon title="支持部分缴纳。系统只核销当前选中的年度广告牌账单。"/><div class="payment-actions"><el-button @click="selected=null">重新选择</el-button><el-button type="primary" :loading="saving" :disabled="!amount" @click="save">确认收款</el-button></div></template><el-empty v-else description="请先从左侧选择一笔待收账单"/></section></div></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{receivableApi}from'../api';import{fmtMoney}from'../utils/format';import type{Receivable}from'../types';const route=useRoute(),router=useRouter(),loading=ref(false),saving=ref(false),keyword=ref(''),list=ref<Receivable[]>([]),selected=ref<Receivable|null>(null),amount=ref<number>();const filtered=computed(()=>list.value.filter(r=>r.amount>r.received&&(!keyword.value||`${r.merchantName}${r.contractCode}${r.billboardCode}`.includes(keyword.value)))),remain=computed(()=>selected.value?selected.value.amount-selected.value.received:0);function select(row:Receivable){selected.value=row;amount.value=remain.value}async function save(){if(!selected.value||!amount.value)return;await ElMessageBox.confirm(`确认收到 ${selected.value.merchantName} 款项 ${fmtMoney(amount.value)} 元，并核销当前账单吗？`,'确认收款',{type:'warning'});saving.value=true;try{await receivableApi.pay(selected.value.id,amount.value);ElMessage.success('收款已登记，应收和资金流水已同步更新');router.push(`/receivables/${selected.value.id}`)}finally{saving.value=false}}onMounted(async()=>{loading.value=true;try{list.value=await receivableApi.list({});const id=Number(route.query.receivableId);const row=list.value.find(r=>r.id===id);if(row)select(row)}finally{loading.value=false}});
</script>
<style scoped>.payment-page{max-width:1180px;margin:0 auto}.payment-layout{display:grid;grid-template-columns:minmax(360px,.9fr) minmax(400px,1.1fr);border:1px solid #d9e2ec}.bill-picker{padding:20px;border-right:1px solid #d9e2ec;background:#f7f9fc}.bill-picker h3{margin:0 0 12px;color:#243a55}.bill-search{margin-bottom:10px}.bill-list{max-height:560px;overflow:auto}.bill-list button{display:flex;width:100%;justify-content:space-between;gap:12px;padding:14px 12px;border:0;border-bottom:1px solid #dfe6ef;background:#fff;text-align:left;cursor:pointer}.bill-list button.active{box-shadow:inset 4px 0 #d9a514;background:#edf4fb}.bill-list b,.bill-list small{display:block}.bill-list small{margin-top:5px;color:#7a8797}.bill-list strong{color:#c84040;white-space:nowrap}.payment-form{padding:22px}.payment-form header{margin-bottom:14px;padding-bottom:12px;border-bottom:2px solid #16488a}.payment-form header span{color:#7a8797;font-size:12px}.payment-form header h3{margin:5px 0 0;color:#173b64}.amount-form{margin-top:20px}.red{color:#c84040}.payment-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}@media(max-width:850px){.payment-layout{grid-template-columns:1fr}.bill-picker{border-right:0;border-bottom:1px solid #d9e2ec}}</style>
